"""Channel-neutral observability state for one engine turn.

A :class:`TurnObservabilityContext` records the turn's timestamps and
derives its latency measurements; metric emission happens in the turn
lifecycle. The context is reached through ContextVars, with a resolver hook
so channel packages (voice) can route the lookup through their own
call-scoped state.
"""

from __future__ import annotations

import time
from contextlib import contextmanager
from contextvars import ContextVar
from typing import Callable, Iterator, Optional

from pydantic import BaseModel, ConfigDict, Field

from rasa.tracing.turn.attribute_values import (
    TurnOutcome,
    TurnOutputModality,
    TurnTriggerType,
)

# ---------------------------------------------------------------------------
# State models
# ---------------------------------------------------------------------------


class TurnInputAnchor(BaseModel):
    """Channel-side fact about the input that triggered the turn being processed.

    Bound by the processor seam that dequeues the user's input, so the engine
    turn can measure latency from the moment the input completed rather than
    from when processing started.
    """

    model_config = ConfigDict(frozen=True)

    input_type: TurnTriggerType
    # Process-local time when the user's input completed. ``None`` means no
    # input-to-output latency can be measured.
    triggered_at_monotonic: Optional[float] = None


class TurnObservabilityContext(BaseModel):
    """Observability state for one engine turn.

    All timestamps are monotonic, so measurements survive wall-clock
    adjustments. When available, the input-trigger timestamp includes queueing
    and composition before processing.

    Turns without an ``input_type`` emit no metrics. First-output latency uses
    only the expected modality; internal text does not count as voice output.
    """

    index: int = 0

    input_type: Optional[TurnTriggerType] = None
    output_modality: Optional[TurnOutputModality] = None
    processing_started_monotonic: float = Field(
        default_factory=lambda: time.monotonic()
    )
    input_triggered_monotonic: Optional[float] = None
    first_text_output_monotonic: Optional[float] = None
    first_audio_output_monotonic: Optional[float] = None

    # Outcome signals reported during the turn.
    interrupted: bool = False
    cancelled: bool = False
    errored: bool = False

    @property
    def user_perceived_latency_ms(self) -> Optional[float]:
        """Latency from the turn's input trigger to its first output (ms).

        On voice, the first TTS audio is what actually reaches the user, so
        it wins over any text output.

        Returns:
            The latency in ms, or ``None`` when the turn produced no
            perceivable output.
        """
        output_monotonic = (
            self.first_audio_output_monotonic
            if self.first_audio_output_monotonic is not None
            else self.first_text_output_monotonic
        )
        if output_monotonic is None or self.input_triggered_monotonic is None:
            return None
        return max(0.0, (output_monotonic - self.input_triggered_monotonic) * 1000)

    def record_first_text_output(self, at_monotonic: Optional[float] = None) -> None:
        """Record the earliest streamed token or committed agent message.

        Args:
            at_monotonic: Monotonic timestamp of the output; defaults to now.
                An earlier timestamp replaces the current anchor.
        """
        self.first_text_output_monotonic = _earliest_monotonic(
            self.first_text_output_monotonic, at_monotonic
        )

    def record_first_audio_output(self, at_monotonic: Optional[float] = None) -> None:
        """Record the earliest generated TTS audio chunk.

        Args:
            at_monotonic: Monotonic timestamp of the output; defaults to now.
                An earlier timestamp replaces the current anchor.
        """
        self.first_audio_output_monotonic = _earliest_monotonic(
            self.first_audio_output_monotonic, at_monotonic
        )

    def record_interrupted(self) -> None:
        """Record that the turn was interrupted, such as by a voice barge-in."""
        self.interrupted = True

    def record_cancelled(self) -> None:
        """Record that call teardown or shutdown cancelled the turn."""
        self.cancelled = True

    def record_error(self) -> None:
        """Record that the engine reported a failure for the turn."""
        self.errored = True

    def turn_outcome(self) -> TurnOutcome:
        """Return the terminal outcome for the turn metrics.

        Interruption takes precedence over cancellation, which takes precedence
        over error.
        """
        if self.interrupted:
            return TurnOutcome.INTERRUPTED
        if self.cancelled:
            return TurnOutcome.CANCELLED
        if self.errored:
            return TurnOutcome.ERROR
        return TurnOutcome.COMPLETED

    @classmethod
    def from_input_anchor(
        cls,
        anchor: Optional[TurnInputAnchor],
        *,
        output_modality: TurnOutputModality,
        index: int = 0,
    ) -> "TurnObservabilityContext":
        """Build a turn context from an input anchor.

        Without an anchor the turn has no ``input_type`` and stays ineligible
        for turn metrics.
        """
        return cls(
            index=index,
            input_type=anchor.input_type if anchor is not None else None,
            input_triggered_monotonic=(
                anchor.triggered_at_monotonic if anchor is not None else None
            ),
            output_modality=output_modality,
        )

    def calculate_turn_duration_seconds(self) -> float:
        """Calculate the processing duration up to the moment of this call."""
        return time.monotonic() - self.processing_started_monotonic

    def calculate_time_to_first_output_seconds(self) -> Optional[float]:
        """Calculate latency from the input trigger to the first output.

        Only output in the turn's output modality counts; internal text is
        not a voice turn's first output.

        Returns:
            The latency in seconds, or ``None`` when the turn has no input
            timestamp, no output modality, or produced no output in it.
        """
        if self.output_modality is None or self.input_triggered_monotonic is None:
            return None
        first_output_monotonic = (
            self.first_audio_output_monotonic
            if self.output_modality is TurnOutputModality.AUDIO
            else self.first_text_output_monotonic
        )
        if first_output_monotonic is None:
            return None
        return first_output_monotonic - self.input_triggered_monotonic


# ---------------------------------------------------------------------------
# Context bindings
# ---------------------------------------------------------------------------


_current_turn_input_anchor: ContextVar[Optional[TurnInputAnchor]] = ContextVar(
    "rasa_turn_input_anchor", default=None
)
_current_turn_context: ContextVar[Optional[TurnObservabilityContext]] = ContextVar(
    "rasa_turn_observability_context", default=None
)


@contextmanager
def bind_turn_input_anchor(
    anchor: Optional[TurnInputAnchor],
) -> Iterator[Optional[TurnInputAnchor]]:
    """Bind the input anchor for the duration of one engine turn.

    ``None`` (a lifecycle turn with no user input) binds nothing, so callers
    can pass an unmapped event's anchor without a conditional.

    Yields:
        The bound anchor, or ``None``. The previous binding is restored on exit.
    """
    if anchor is None:
        yield None
        return
    token = _current_turn_input_anchor.set(anchor)
    try:
        yield anchor
    finally:
        _current_turn_input_anchor.reset(token)


@contextmanager
def bind_turn_observability_context(
    context: TurnObservabilityContext,
) -> Iterator[TurnObservabilityContext]:
    """Bind the context for the duration of one engine turn.

    Yields:
        The bound context. The previous binding is restored on exit.
    """
    token = _current_turn_context.set(context)
    try:
        yield context
    finally:
        _current_turn_context.reset(token)


# ---------------------------------------------------------------------------
# Resolver hook
# ---------------------------------------------------------------------------

# Channel packages own turn state that outlives a single ContextVar scope —
# voice turns live on the call context that channel tasks inherit. This
# neutral package cannot import channel code, so a channel registers a
# resolver here and the accessor consults it before the neutral binding.
_active_turn_resolver: Optional[Callable[[], Optional[TurnObservabilityContext]]] = None


def set_active_turn_resolver(
    resolver: Callable[[], Optional[TurnObservabilityContext]],
) -> None:
    """Register the channel-side lookup for the active turn (single slot)."""
    global _active_turn_resolver
    _active_turn_resolver = resolver


# ---------------------------------------------------------------------------
# Accessors
# ---------------------------------------------------------------------------


def get_current_turn_input_anchor() -> Optional[TurnInputAnchor]:
    """Return the input anchor of the turn being processed, if any."""
    return _current_turn_input_anchor.get()


def get_current_turn_observability_context() -> Optional[TurnObservabilityContext]:
    """Return the active turn's observability state, or ``None``.

    A turn resolved through the registered channel resolver (voice turns on
    the call context) wins over the channel-neutral binding. ``None`` outside
    an active turn — including whenever observability (tracing and metrics)
    is disabled.
    """
    if _active_turn_resolver is not None:
        turn = _active_turn_resolver()
        if turn is not None:
            return turn
    return _current_turn_context.get()


# ---------------------------------------------------------------------------
# Recording helpers
# ---------------------------------------------------------------------------


def record_turn_first_llm_token() -> None:
    """Record that the active turn just produced its first streamed LLM token.

    Call this at the moment the first content delta arrives, so "now" is the
    token's arrival time.
    """
    if (turn := get_current_turn_observability_context()) is not None:
        turn.record_first_text_output(time.monotonic())


def record_turn_bot_message() -> None:
    """Record the first agent message committed during the active turn."""
    if (turn := get_current_turn_observability_context()) is not None:
        turn.record_first_text_output()


def record_turn_interrupted() -> None:
    """Record that the active turn was interrupted."""
    if (turn := get_current_turn_observability_context()) is not None:
        turn.record_interrupted()


def record_turn_error() -> None:
    """Record that the engine reported a failure for the active turn."""
    if (turn := get_current_turn_observability_context()) is not None:
        turn.record_error()


# ---------------------------------------------------------------------------
# Private helpers
# ---------------------------------------------------------------------------


def _earliest_monotonic(current: Optional[float], reported: Optional[float]) -> float:
    at_monotonic = reported if reported is not None else time.monotonic()
    if current is None:
        return at_monotonic
    return min(current, at_monotonic)
